-- evt:ambrose
RegisterEvent(2, "Griffin's perch", function(continueStep)
    local eventId = 2
    if continueStep == 1 then
        XeenQuests.hook("m27.fly_out")
        return
    end
    if continueStep ~= nil then
        return
    end
    if not XeenQuests.can("m27.fly_out") then
        evt.StatusText("A griffin's perch, empty.")
        return
    end
    AskChoiceWithAnswerSteps(eventId, 3, "Are you ready to leave this awful place, friends?", {{Answer = "Yes", Step = 1}, {Answer = "No", Step = 2}})
end, "Griffin's perch")

